// One reviewed app dependency update; package-lock is generated by npm, never hand edited.
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { createHash } from "node:crypto";
import { createReadStream } from "node:fs";
import { access,readdir,readFile,writeFile } from "node:fs/promises";
import path from "node:path";
import { createOwnedRuntimeScratch } from "./lib/owned-runtime-scratch.mjs";
import { prepareOgNodeRuntime } from "./lib/prepare-og-node-runtime.mjs";
const root=path.resolve(import.meta.dirname,".."),destination=path.join(root,"evidence/2026-10-29-og-security-install.json");
await assert.rejects(access(destination),{code:"ENOENT"});
const sha=b=>createHash("sha256").update(b).digest("hex");
async function engines(){const out={};async function walk(dir){for(const entry of await readdir(dir,{withFileTypes:true})){
  assert.equal(entry.isSymbolicLink(),false);const file=path.join(dir,entry.name);
  if(entry.isDirectory())await walk(file);else if(entry.isFile()&&entry.name.endsWith(".wasm")){
    const h=createHash("sha256");for await(const bytes of createReadStream(file,{highWaterMark:262144}))h.update(bytes);
    out[path.relative(root,file).replaceAll("\\","/")]=h.digest("hex");}}}await walk(path.join(root,"public/engines"));return out;}
const beforeLock=await readFile(path.join(root,"package-lock.json"));assert.equal(sha(beforeLock),"b2c97a14d64528607b8acd6394350ea741db853de36fcd2f4d46789c4b3964a4");
const manifestBytes=await readFile(path.join(root,"package.json")),manifest=JSON.parse(manifestBytes);
assert.equal(manifest.overrides["vinext@0.0.50"]["@vercel/og"],"1.0.3");assert.equal(manifest.overrides["satori@0.33.5"].fflate,"0.7.5");
const report={schemaVersion:1,startedAt:new Date().toISOString(),scope:"Reviewed framework dependency update only; conversion/memory/security-release acceptance remains separate",beforeLockSha256:sha(beforeLock),manifestSha256:sha(manifestBytes),publicEnginesBefore:await engines(),status:"running"};
const runtime=await createOwnedRuntimeScratch("og-security-install-");
try{
  const cli=path.join(path.dirname(process.execPath),"node_modules/npm/bin/npm-cli.js");
  const result=spawnSync(process.execPath,[cli,"install","--ignore-scripts","--no-audit","--no-fund"],
    {cwd:root,env:{...runtime.env,npm_config_cache:path.join(runtime.directory,"npm-cache"),npm_config_update_notifier:"false"},windowsHide:true,encoding:"utf8",timeout:180000,maxBuffer:131072});
  assert.ifError(result.error);assert.equal(result.status,0,result.stderr);report.installLogTail=result.stdout.slice(-2048);
  report.bootstrap=await prepareOgNodeRuntime(root);report.afterLockSha256=sha(await readFile(path.join(root,"package-lock.json")));
  assert.equal(sha(await readFile(path.join(root,"package.json"))),report.manifestSha256);
  report.publicEnginesAfter=await engines();assert.deepEqual(report.publicEnginesAfter,report.publicEnginesBefore);
  report.status="installed-scoped-og-satori-fflate-remedy-bootstrap-applied-public-engines-unchanged";
}catch(error){report.status="failed-og-security-install";report.failure=String(error.stack??error);process.exitCode=1;}
finally{await runtime.close();report.ownedScratchRemoved=true;report.finishedAt=new Date().toISOString();await writeFile(destination,JSON.stringify(report,null,2)+"\n",{flag:"wx"});}
console.log(JSON.stringify({path:path.relative(root,destination),status:report.status,cleanup:report.ownedScratchRemoved,publicEngines:Object.keys(report.publicEnginesBefore).length,failure:report.failure}));
